import osimport librosaimport librosa.displayimport sounddevice as sdimport numpy as npimport matplotlib.pyplot as pltfrom matplotlib import colormaps as mcmfrom stft import stft, RMSEng, plot_comparison_spectrograms, Mfcc# Base pathbase_path = "/Users/satnamsingh/Downloads/Audio_Speech_Actors_01-24"# Emotion mappingemotion_map = {    '01': 'neutral',    '02': 'calm',    '03': 'happy',    '04': 'sad',    '05': 'angry',    '06': 'fearful',    '07': 'disgust',    '08': 'surprised'}# Function to parse filename and extract emotiondef get_emotion_from_filename(filename):    """Extract emotion code from RAVDESS filename"""    parts = filename.split('-')    if len(parts) >= 3:        emotion_code = parts[2]        return emotion_code, emotion_map.get(emotion_code, 'unknown')    return None, None# Get all actor foldersactor_folders = sorted([f for f in os.listdir(base_path) if f.startswith('Actor_')])# Specify which emotions you want to comparetarget_emotions = ['happy', 'sad']# Example: Read files from a specific actoractor_id = 1actor_folder = os.path.join(base_path, f'Actor_{actor_id:02d}')# Get all wav files for this actorwav_files = [f for f in os.listdir(actor_folder) if f.endswith('.wav')]# Dictionary to store emotion dataemotion_data = {}for target_emotion in target_emotions:    # Filter files by emotion    filtered_files = []    for wav_file in wav_files:        emotion_code, emotion_label = get_emotion_from_filename(wav_file)        if emotion_label == target_emotion:            filtered_files.append(wav_file)        print(f"Found {len(filtered_files)} files with emotion: {target_emotion}")        # Take first file of this emotion    if filtered_files:        filepath = os.path.join(actor_folder, filtered_files[0])        audio_signal, sample_rate = librosa.load(filepath, sr=None)                print(f"Processing: {filtered_files[0]} - {target_emotion}")        print(f"Duration: {len(audio_signal)/sample_rate:.2f}s, Sample rate: {sample_rate} Hz")                # Extract RMS energy        rms_energy = RMSEng(audio_signal, 512, 2048)                # Short time fourier transform        stfft = stft(audio_signal, 512, 2048)        spectrogram_db = 20 * np.log10(stfft + 1e-10)                # Create time axis        frames = np.arange(len(rms_energy))        time_energy = librosa.frames_to_time(frames, sr=sample_rate, hop_length=512)                # ============================================        # MFCC COMPARISON: Your implementation vs Librosa        # ============================================                # Parameters        win_length = 400        n_mfcc = 13        n_mels = 40  # Number of mel filters                # Your MFCC implementation        print(f"\nCalculating MFCC using custom implementation...")        mfcc_custom = Mfcc(audio_signal, sample_rate, win_length, n_mels, n_fft=2048)                # Librosa MFCC implementation        print(f"Calculating MFCC using librosa...")        mfcc_librosa = librosa.feature.mfcc(            y=audio_signal,            sr=sample_rate,            n_mfcc=n_mfcc,            n_fft=2048,            hop_length=512,            n_mels=n_mels,            window='hamming'        )                # Transpose librosa output to match your format (frames x coefficients)        mfcc_librosa = mfcc_librosa.T                print(f"\nMFCC Shapes:")        print(f"  Custom implementation: {mfcc_custom.shape}")        print(f"  Librosa implementation: {mfcc_librosa.shape}")                # Calculate differences        min_frames = min(mfcc_custom.shape[0], mfcc_librosa.shape[0])        mfcc_custom_trimmed = mfcc_custom[:min_frames, :]        mfcc_librosa_trimmed = mfcc_librosa[:min_frames, :]                # Mean Absolute Error        mae = np.mean(np.abs(mfcc_custom_trimmed - mfcc_librosa_trimmed))                # Root Mean Square Error        rmse = np.sqrt(np.mean((mfcc_custom_trimmed - mfcc_librosa_trimmed) ** 2))                # Correlation coefficient for each MFCC coefficient        correlations = []        for coef in range(n_mfcc):            corr = np.corrcoef(mfcc_custom_trimmed[:, coef],                               mfcc_librosa_trimmed[:, coef])[0, 1]            correlations.append(corr)                print(f"\nMFCC Comparison Statistics:")        print(f"  Mean Absolute Error: {mae:.6f}")        print(f"  Root Mean Square Error: {rmse:.6f}")        print(f"  Average Correlation: {np.mean(correlations):.6f}")        print(f"  Min Correlation: {np.min(correlations):.6f}")        print(f"  Max Correlation: {np.max(correlations):.6f}")                # Store data        emotion_data[target_emotion] = {            'audio': audio_signal,            'sample_rate': sample_rate,            'energy': rms_energy,            'time_energy': time_energy,            'filename': filtered_files[0],            'mfcc_custom': mfcc_custom,            'mfcc_librosa': mfcc_librosa,            'mfcc_mae': mae,            'mfcc_rmse': rmse,            'mfcc_correlations': correlations        }# ============================================# PLOTTING: Energy and MFCC Comparison# ============================================plt.figure(figsize=(16, 12))# Subplot 1: Waveformsplt.subplot(4, 2, 1)for emotion in target_emotions:    data = emotion_data[emotion]    time_audio = np.linspace(0, len(data['audio'])/data['sample_rate'], len(data['audio']))    plt.plot(time_audio, data['audio'], label=emotion.capitalize(), alpha=0.7)plt.xlabel('Time (s)')plt.ylabel('Amplitude')plt.title('Waveform Comparison')plt.legend()plt.grid(True, alpha=0.3)# Subplot 2: Energy (RMS) overlaidplt.subplot(4, 2, 2)for emotion in target_emotions:    data = emotion_data[emotion]    plt.plot(data['time_energy'], data['energy'], label=emotion.capitalize(), linewidth=2)plt.xlabel('Time (s)')plt.ylabel('RMS Energy')plt.title('Energy Comparison (Overlaid)')plt.legend()plt.grid(True, alpha=0.3)# Subplot 3 & 4: MFCC heatmaps for first emotion (Custom vs Librosa)emotion_1 = target_emotions[0]data_1 = emotion_data[emotion_1]plt.subplot(4, 2, 3)plt.imshow(data_1['mfcc_custom'].T, aspect='auto', origin='lower', cmap='viridis')plt.colorbar(label='MFCC Value')plt.xlabel('Frame')plt.ylabel('MFCC Coefficient')plt.title(f'{emotion_1.capitalize()} - Custom MFCC')plt.subplot(4, 2, 4)plt.imshow(data_1['mfcc_librosa'].T, aspect='auto', origin='lower', cmap='viridis')plt.colorbar(label='MFCC Value')plt.xlabel('Frame')plt.ylabel('MFCC Coefficient')plt.title(f'{emotion_1.capitalize()} - Librosa MFCC')# Subplot 5 & 6: MFCC heatmaps for second emotion (Custom vs Librosa)if len(target_emotions) > 1:    emotion_2 = target_emotions[1]    data_2 = emotion_data[emotion_2]        plt.subplot(4, 2, 5)    plt.imshow(data_2['mfcc_custom'].T, aspect='auto', origin='lower', cmap='viridis')    plt.colorbar(label='MFCC Value')    plt.xlabel('Frame')    plt.ylabel('MFCC Coefficient')    plt.title(f'{emotion_2.capitalize()} - Custom MFCC')        plt.subplot(4, 2, 6)    plt.imshow(data_2['mfcc_librosa'].T, aspect='auto', origin='lower', cmap='viridis')    plt.colorbar(label='MFCC Value')    plt.xlabel('Frame')    plt.ylabel('MFCC Coefficient')    plt.title(f'{emotion_2.capitalize()} - Librosa MFCC')# Subplot 7: Correlation per MFCC coefficientplt.subplot(4, 2, 7)x = np.arange(n_mfcc)width = 0.35for i, emotion in enumerate(target_emotions):    data = emotion_data[emotion]    plt.bar(x + i*width, data['mfcc_correlations'], width,             label=emotion.capitalize(), alpha=0.8)plt.xlabel('MFCC Coefficient')plt.ylabel('Correlation')plt.title('Correlation: Custom vs Librosa (per coefficient)')plt.xticks(x + width/2, [f'C{i}' for i in range(n_mfcc)])plt.legend()plt.grid(True, alpha=0.3, axis='y')plt.axhline(y=0.95, color='r', linestyle='--', alpha=0.5, label='0.95 threshold')# Subplot 8: Error metrics comparisonplt.subplot(4, 2, 8)emotions_list = list(emotion_data.keys())mae_values = [emotion_data[e]['mfcc_mae'] for e in emotions_list]rmse_values = [emotion_data[e]['mfcc_rmse'] for e in emotions_list]x = np.arange(len(emotions_list))width = 0.35plt.bar(x - width/2, mae_values, width, label='MAE', alpha=0.8)plt.bar(x + width/2, rmse_values, width, label='RMSE', alpha=0.8)plt.xlabel('Emotion')plt.ylabel('Error')plt.title('MFCC Error Metrics')plt.xticks(x, [e.capitalize() for e in emotions_list])plt.legend()plt.grid(True, alpha=0.3, axis='y')plt.tight_layout()plt.show()# ============================================# DETAILED STATISTICS# ============================================print("\n" + "="*60)print("DETAILED MFCC COMPARISON STATISTICS")print("="*60)for emotion in target_emotions:    data = emotion_data[emotion]    print(f"\n{emotion.upper()}:")    print(f"  File: {data['filename']}")    print(f"  MFCC Shape: {data['mfcc_custom'].shape}")    print(f"  Mean Absolute Error: {data['mfcc_mae']:.6f}")    print(f"  Root Mean Square Error: {data['mfcc_rmse']:.6f}")    print(f"  Average Correlation: {np.mean(data['mfcc_correlations']):.6f}")    print(f"\n  Per-coefficient correlations:")    for i, corr in enumerate(data['mfcc_correlations']):        print(f"    MFCC-{i}: {corr:.6f}")print("\n" + "="*60)print("ENERGY STATISTICS")print("="*60)for emotion in target_emotions:    data = emotion_data[emotion]    print(f"\n{emotion.upper()}:")    print(f"  Mean Energy: {np.mean(data['energy']):.6f}")    print(f"  Std Energy: {np.std(data['energy']):.6f}")    print(f"  Max Energy: {np.max(data['energy']):.6f}")    print(f"  Min Energy: {np.min(data['energy']):.6f}")